        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.5rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0.75rem 0 0;
        max-width: 60ch;
        color: var(--muted);
      }

