        width: 1.125rem;
        height: 1.125rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .radio-copy {
        display: grid;
        gap: 0.125rem;
      }

      .radio-title {
        font-weight: 600;
      }

      .radio-note {
        color: var(--muted);
        font-size: 0.925rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 1.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.3rem;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, #2563eb, #1d4ed8);
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.24);
        cursor: pointer;
