      }

      .status {
        margin-top: 1rem;
        min-height: 1.5rem;
        color: var(--accent);
        font-weight: 600;
      }

      @media (max-width: 520px) {
        .card {
          padding: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: CanvasText;
          --border-strong: CanvasText;
          --accent: Highlight;
          --accent-soft: Highlight;
        }

        .card,
        .form-field,
        .radio-option,
        button {
          forced-color-adjust: auto;
        }

        .radio-option:focus-within,
        button:focus-visible {
          outline: 2px solid Highlight;
          box-shadow: none;
        }
