        border-radius: 18px;
        padding: 1.25rem;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-inline-size: 0;
      }

      legend {
        padding: 0;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .required {
        color: var(--accent);
      }

      .help-text {
        margin: 0.5rem 0 0;
        color: var(--muted);
      }

      .radio-list {
        display: grid;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.875rem;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: var(--surface);
        cursor: pointer;
        transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      .radio-option:hover {
        border-color: var(--border-strong);
        transform: translateY(-1px);
      }

      .radio-option:focus-within {
        border-color: var(--accent);
        box-shadow: 0 0 0 4px var(--accent-soft);
      }

      .radio-option input {
        width: 1.125rem;
        height: 1.125rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .radio-copy {
        display: grid;
        gap: 0.125rem;
      }

      .radio-title {
        font-weight: 600;
      }

      .radio-note {
        color: var(--muted);
        font-size: 0.925rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 1.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.3rem;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, #2563eb, #1d4ed8);
        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.24);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.35);
        outline-offset: 3px;
      }

      .status {
        margin-top: 1rem;
        min-height: 1.5rem;
        color: var(--accent);
        font-weight: 600;
      }

      @media (max-width: 520px) {
        .card {
          padding: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: CanvasText;
          --border-strong: CanvasText;
          --accent: Highlight;
          --accent-soft: Highlight;
        }

        .card,
        .form-field,
        .radio-option,
        button {
          forced-color-adjust: auto;
        }

        .radio-option:focus-within,
        button:focus-visible {
          outline: 2px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content"></main>

    <script>
      const notificationOptions = [
        {
          id: "notify-email",
          value: "email",
          label: "Email",
          note: "Best for detailed updates and receipts."
        },
        {
          id: "notify-sms",
          value: "sms",
          label: "SMS",
          note: "Good for quick, time-sensitive alerts."
        },
        {
          id: "notify-push",
          value: "push",
          label: "Push Notifications",
          note: "Great for instant updates in the app."
        }
      ];

      const RadioOption = ({ id, value, label, note }) => `
        <label class="radio-option" for="${id}">
          <input id="${id}" name="notification-preference" type="radio" value="${value}" required />
          <span class="radio-copy">
            <span class="radio-title">${label}</span>
            <span class="radio-note">${note}</span>
          </span>
        </label>
      `;

      const NotificationForm = () => `
        <section class="card" aria-labelledby="page-title">
          <p class="eyebrow">Preferences</p>
          <h1 id="page-title">Notification settings</h1>
          <p class="intro">Choose the channel you prefer for account updates and alerts.</p>

          <form id="notification-form" novalidate>
            <div class="form-field">
              <fieldset aria-describedby="notification-help">
                <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
                <p class="help-text" id="notification-help">Select one option before continuing.</p>
                <div class="radio-list">
                  ${notificationOptions.map(RadioOption).join("")}
                </div>
              </fieldset>
            </div>

            <div class="actions">
              <button type="submit">Save preference</button>
            </div>

            <p class="status" id="form-status" aria-live="polite"></p>
          </form>
        </section>
      `;

      document.getElementById("main-content").innerHTML = NotificationForm();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const value = new FormData(form).get("notification-preference");
        const selected = notificationOptions.find((option) => option.value === value);
        status.textContent = selected
          ? `Saved preference: ${selected.label}.`
          : "";
      });
    </script>
  </body>
</html>
