           value: "sms",
           label: "SMS",
           note: "Good for quick, time-sensitive alerts."
         },
         {
           id: "notify-push",
           value: "push",
           label: "Push Notifications",
           note: "Great for instant updates in the app."
         }
       ];

       const RadioOption = ({ id, value, label, note }) => `
         <label class="radio-option" for="${id}">
           <input id="${id}" name="notification-preference" type="radio" value="${value}" required />
