             <span class="radio-title">${label}</span>
             <span class="radio-note">${note}</span>
           </span>
         </label>
       `;

       const NotificationForm = () => `
         <section class="card" aria-labelledby="page-title">
           <p class="eyebrow">Preferences</p>
           <h1 id="page-title">Notification settings</h1>
           <p class="intro">Choose the channel you prefer for account updates and alerts.</p>

           <form id="notification-form" novalidate>
             <div class="form-field">
               <fieldset aria-describedby="notification-help">
                 <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
                 <p class="help-text" id="notification-help">Select one option before continuing.</p>
                 <div class="radio-list">
                   ${notificationOptions.map(RadioOption).join("")}
                 </div>
               </fieldset>
             </div>

             <div class="actions">
               <button type="submit">Save preference</button>
             </div>

             <p class="status" id="form-status" aria-live="polite"></p>
           </form>
         </section>
       `;

       document.getElementById("main-content").innerHTML = NotificationForm();

       const form = document.getElementById("notification-form");
       const status = document.getElementById("form-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const value = new FormData(form).get("notification-preference");
         const selected = notificationOptions.find((option) => option.value === value);
