  const submitStatus = await page.evaluate(async () => {
    const form = document.getElementById('notification-form');
    form.querySelector('button[type="submit"]').click();
    await new Promise(requestAnimationFrame);
    return {
      valid: form.checkValidity(),
      status: document.getElementById('form-status').textContent,
      activeTag: document.activeElement && document.activeElement.tagName,
      activeType: document.activeElement && document.activeElement.type,
      activeName: document.activeElement && document.activeElement.name
    };
  });
  await browser.close();

  const violations = results.violations.filter(v => !v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    violations: violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    submitStatus
  }, null, 2));
  process.exit(violations.length ? 1 : 0);
})().catch(err => {
  console.error(err);
  process.exit(1);
});
